using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using System.Text;
using NUnit.Framework;

namespace OnlyWorlds.Sdk.Tests.Editor
{
    /// <summary>
    /// The NFC every <c>.owworld</c> reader uses before it folds a name (folder spec §4.7, OW-18): Unicode 15.1's,
    /// built from UnicodeData.txt and CompositionExclusions.txt (<c>OWNfcData</c>, generated by <c>tools/gen_nfc.py</c>),
    /// never the runtime's <c>string.Normalize</c>.
    /// </summary>
    /// <remarks>
    /// <para>
    /// The proof is Unicode's own: <c>NormalizationTest-15.1.0.txt</c>, vendored in <c>Tests/Editor/Fixtures/unicode~/</c>
    /// (the trailing <c>~</c> keeps Unity from importing 2.6 MB of text) and pinned by sha256. Every line's NFC
    /// invariants hold, and every code point its Part 1 does not list is its own NFC. The test file is the normalizer's
    /// check only: the reader's rule reads the two data files alone.
    /// </para>
    /// <para>
    /// <c>OWNfc</c> is internal to the runtime assembly, which exposes no internals, so it is reached by reflection, as
    /// <c>OWCaseFoldTests</c> reaches the fold; the archive's refusals test it through <see cref="OWWorldArchive.Read"/>.
    /// </para>
    /// </remarks>
    public class OWNfcTests
    {
        private const string TestFile = "NormalizationTest-15.1.0.txt";

        /// <summary>NormalizationTest-15.1.0.txt's sha256, as the fixture workshop's README records it.</summary>
        private const string TestFileSha256 = "871238e37e3be0696ec2bd0891119a041b052da1a84485eda05a5438724b223e";

        private static readonly Assembly Runtime = typeof(OWWorldArchive).Assembly;
        private static readonly Type NfcType = Runtime.GetType("OnlyWorlds.Sdk.OWNfc", true);
        private static readonly Type DataType = Runtime.GetType("OnlyWorlds.Sdk.OWNfcData", true);

        private static readonly Func<string, string> Nfc = Method<Func<string, string>>(NfcType, "Normalize");

        private static T Method<T>(Type type, string name) where T : Delegate
            => (T)Delegate.CreateDelegate(typeof(T), type.GetMethod(name, BindingFlags.Static | BindingFlags.NonPublic));

        private static T Constant<T>(string name)
            => (T)DataType.GetField(name, BindingFlags.Static | BindingFlags.NonPublic).GetValue(null);

        private static string Hex(string s)
        {
            var parts = new List<string>();
            for (var i = 0; i < s.Length; i++)
            {
                var cp = char.ConvertToUtf32(s, i);
                if (cp > 0xFFFF) i++;
                parts.Add(cp.ToString("X4", CultureInfo.InvariantCulture));
            }

            return string.Join(" ", parts);
        }

        private static string Sha256(byte[] bytes)
        {
            using var sha = SHA256.Create();
            return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-", string.Empty).ToLowerInvariant();
        }

        /// <summary>The vendored test file, or null (the test is then ignored, saying where it looked).</summary>
        private static string TestFilePath(out string looked)
        {
            string root = null;
            try
            {
                var package = UnityEditor.PackageManager.PackageInfo.FindForAssembly(typeof(OWNfcTests).Assembly);
                if (package != null) root = package.resolvedPath;
            }
            catch (Exception)
            {
                // No Editor behind the call; the working directory below.
            }

            root ??= Path.Combine(Directory.GetCurrentDirectory(), "Packages", "com.onlyworlds.sdk");
            looked = Path.Combine(root, "Tests", "Editor", "Fixtures", "unicode~", TestFile);
            return File.Exists(looked) ? looked : null;
        }

        private static string[] ReadTestFile()
        {
            var path = TestFilePath(out var looked);
            if (path == null) Assert.Ignore($"{TestFile} not found at {looked}");
            var bytes = File.ReadAllBytes(path);
            Assert.AreEqual(TestFileSha256, Sha256(bytes), $"{TestFile} is not Unicode's 15.1.0 file.");
            return Encoding.UTF8.GetString(bytes).Split('\n');
        }

        [Test]
        public void NormalizationTest_EveryLine_HoldsItsNfcInvariants()
        {
            // c2 == NFC(c1) == NFC(c2) == NFC(c3) and c4 == NFC(c4) == NFC(c5), on every line of every part.
            var lines = 0;
            var bad = new List<string>();
            foreach (var raw in ReadTestFile())
            {
                var hash = raw.IndexOf('#');
                var line = (hash < 0 ? raw : raw.Substring(0, hash)).Trim();
                if (line.Length == 0 || line.StartsWith("@Part", StringComparison.Ordinal)) continue;

                var c = line.Split(';').Take(5).Select(col => string.Concat(col.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries)
                    .Select(x => char.ConvertFromUtf32(int.Parse(x, NumberStyles.HexNumber, CultureInfo.InvariantCulture))))).ToArray();
                lines++;

                var nfc = new[] { Nfc(c[0]), Nfc(c[1]), Nfc(c[2]), Nfc(c[3]), Nfc(c[4]) };
                if (c[1] == nfc[0] && c[1] == nfc[1] && c[1] == nfc[2] && c[3] == nfc[3] && c[3] == nfc[4]) continue;
                if (bad.Count < 20) bad.Add($"{line}  ->  NFC(c1) = {Hex(nfc[0])}, NFC(c3) = {Hex(nfc[2])}, NFC(c5) = {Hex(nfc[4])}");
                else bad.Add(null);
            }

            TestContext.WriteLine($"{TestFile}: {lines} lines, {bad.Count} mismatches");
            Assert.AreEqual(19074, lines, "The 15.1.0 file has 19,074 test lines.");
            Assert.IsEmpty(bad, string.Join("\n", bad.Where(b => b != null)));
        }

        [Test]
        public void NormalizationTest_EveryCodePointPart1DoesNotList_IsItsOwnNfc()
        {
            var listed = new HashSet<int>();
            var inPart1 = false;
            foreach (var raw in ReadTestFile())
            {
                var line = raw.Split('#')[0].Trim();
                if (line.StartsWith("@Part", StringComparison.Ordinal))
                {
                    inPart1 = line == "@Part1";
                    continue;
                }

                if (inPart1 && line.Length > 0) listed.Add(int.Parse(line.Split(';')[0].Trim(), NumberStyles.HexNumber, CultureInfo.InvariantCulture));
            }

            var bad = new List<string>();
            var checkedCount = 0;
            for (var cp = 0; cp <= 0x10FFFF; cp++)
            {
                if (cp >= 0xD800 && cp <= 0xDFFF || listed.Contains(cp)) continue;
                checkedCount++;
                var one = char.ConvertFromUtf32(cp);
                if (Nfc(one) != one) bad.Add($"U+{cp:X4} -> {Hex(Nfc(one))}");
            }

            TestContext.WriteLine($"Part 1 lists {listed.Count} code points; {checkedCount} others checked, {bad.Count} not their own NFC");
            Assert.Greater(listed.Count, 0, "Part 1 was not read.");
            Assert.IsEmpty(bad, string.Join("\n", bad.Take(20)));
        }

        [Test]
        public void TheDerivedSets_AreTheGeneratorsDerivation()
        {
            // OWNfc derives Full_Composition_Exclusion and the primary composites from the files' facts at run time;
            // the generator derives them in Python, as the reference checker does. Both must reach the same sets.
            var excluded = (int[])NfcType.GetMethod("FullCompositionExclusion", BindingFlags.Static | BindingFlags.NonPublic).Invoke(null, null);
            var composites = (int[])NfcType.GetMethod("PrimaryComposites", BindingFlags.Static | BindingFlags.NonPublic).Invoke(null, null);

            var excludedLines = string.Concat(excluded.Select(cp => cp.ToString("X4", CultureInfo.InvariantCulture) + "\n"));
            var compositeLines = new StringBuilder();
            for (var i = 0; i < composites.Length; i += 3)
            {
                compositeLines.Append(composites[i].ToString("X4", CultureInfo.InvariantCulture)).Append(' ')
                    .Append(composites[i + 1].ToString("X4", CultureInfo.InvariantCulture)).Append(';')
                    .Append(composites[i + 2].ToString("X4", CultureInfo.InvariantCulture)).Append('\n');
            }

            Assert.AreEqual("15.1.0", Constant<string>("UnicodeVersion"), "Folder spec §4.7 pins NFC at 15.1.0.");
            Assert.AreEqual(Constant<int>("ExcludedCount"), excluded.Length, "Full_Composition_Exclusion's size");
            Assert.AreEqual(Constant<string>("ExcludedDigest"), Sha256(Encoding.ASCII.GetBytes(excludedLines)));
            Assert.AreEqual(Constant<int>("CompositeCount"), composites.Length / 3, "the primary composites' count");
            Assert.AreEqual(Constant<string>("CompositeDigest"), Sha256(Encoding.ASCII.GetBytes(compositeLines.ToString())));
        }

        // The set's NFC pairs (fixtures/owworld, the dist's README), each as NFC sees it.
        [TestCase("豈", "豈")] // a singleton
        [TestCase("Å", "Å")] // a singleton, then A U+030A composes to U+00C5
        [TestCase("क़", "क़")] // an excluded composite: both are U+0915 U+093C
        [TestCase("lệ", "lệ")] // canonical ordering: both U+1EC7
        [TestCase("한", "한")] // Hangul by arithmetic
        [TestCase("ΐ", "ΐ")] // a non-starter decomposition: both U+0390
        public void TheSetsNfcPairs_Meet(string a, string b)
        {
            Assert.AreEqual(Hex(Nfc(a)), Hex(Nfc(b)));
        }

        [TestCase("lá̀", "là́")] // marks of one class keep their order
        [TestCase("ﬁ", "fi")] // a compatibility mapping is not canonical
        [TestCase("\U00011383", "\U00011382\U000113C9")] // Tulu-Tigalari, unassigned at 15.1: each its own NFC
        public void TheSetsNfcPairs_StayApart(string a, string b)
        {
            Assert.AreNotEqual(Hex(Nfc(a)), Hex(Nfc(b)));
        }

        [Test]
        public void ACodePointUnassignedAt15_1_IsItsOwnNfc_WhateverTheRuntimeSays()
        {
            // The runtime's string.Normalize is not asked for the answer; it is only reported, so a run says which
            // side of Unicode 16 this runtime's tables are on.
            const string tulu = "\U00011383";
            Assert.AreEqual(tulu, Nfc(tulu));

            string runtime;
            try
            {
                runtime = Hex(tulu.Normalize(NormalizationForm.FormD));
            }
            catch (Exception e)
            {
                runtime = e.GetType().Name;
            }

            TestContext.WriteLine($"this runtime's NFD of U+11383: {runtime} (Unicode 16 says 11382 113C9; 15.1 says 11383)");
        }

        [Test]
        public void AStringBelowStableBelow_ComesBackUntouched()
        {
            Assert.AreEqual(0x0300, Constant<int>("StableBelow"));
            const string ascii = "elements/character/Ruggero-d-Altavilla.json";
            Assert.AreSame(ascii, Nfc(ascii));
            var latin1 = "Città/Caltanissetta/Agrigento Ñ ÿ";
            Assert.AreSame(latin1, Nfc(latin1));
            Assert.AreEqual(string.Empty, Nfc(string.Empty));
        }

        [Test]
        public void ALoneSurrogate_IsRefused_AndTheArchiveFoldsItByCaseAlone()
        {
            Assert.Throws<ArgumentException>(() => Nfc("é\uD801"));
            Assert.Throws<ArgumentException>(() => Nfc("\uDC00é"));

            // OWWorldArchive.Fold catches the refusal and folds the name by case alone, on every runtime. (Before, it
            // was the runtime's call: CoreCLR's string.Normalize refuses a lone surrogate, Mono's normalizes around it.)
            var fold = Method<Func<string, string>>(typeof(OWWorldArchive), "Fold");
            Assert.AreEqual("é\uD801b", fold("É\uD801B"));
            Assert.AreEqual("éb", fold("ÉB"));
        }

        [Test]
        public void ASurrogatePair_IsOneCodePoint()
        {
            // U+1D15E MUSICAL SYMBOL HALF NOTE is an excluded composite (U+1D157 U+1D165): NFC decomposes it.
            Assert.AreEqual("x\U0001D157\U0001D165", Nfc("x\U0001D15E"));
            Assert.AreEqual("\U00010400", Nfc("\U00010400"));
        }
    }
}
